{"command": "cd /workspace/out && python3 - <<'EOF'
import json, re
last={}
for line in open('cde_runs.jsonl'):
    d=json.loads(line); last[d['target_id']]=d
pkg=open('strike_package.md').read(); ann=open('loac_annex.md').read()
csv_rows=[l.strip() for l in open('cde_summary.csv') if l.strip()]
ok=True
def check(cond,msg):
    global ok
    if not cond: ok=False; print('MISMATCH:',msg)
# annex blocks
blocks={b.split(' —')[0]: b for b in ann.split('\n### ')[1:]}
check(len(blocks)==8, f'annex blocks {len(blocks)}')
for tid in sorted(last):
    b=blocks.get(tid)
    if b is None: check(False,f'{tid} no annex block'); continue
    for el in ['Military necessity / military objective','Distinction','Proportionality','Precautions','Conclusion']:
        check(f'**{el}:**' in b, f'{tid} annex missing {el}')
    check('Prepared by JTC for CCJA review.' in ann, 'closing line')
# package per-target fields
for tid in sorted(last):
    d=last[tid]
    sec=pkg.split(f'### {tid} —')[1].split('\n### ')[0]
    fields=dict(re.findall(r'\| ([A-Za-z /]+?) \| (.*?) \|', sec))
    for f in ['BE / MSS object','Location','Function / associated force','PID basis','Desired effect',
              'Weapon class / fuze','TOT window','CDE level','NC casualty estimate / NCV','Occupancy basis',
              'NSL objects within CER','Approval authority','Remarks']:
        check(f in fields, f'{tid} missing/renamed field: {f!r} (got {list(fields)})')
    check(fields['CDE level'].strip()==str(d['cde_level']), f'{tid} level')
    check(fields['Occupancy basis'].startswith(d['occupancy_basis']), f'{tid} occupancy')
    check(fields['Approval authority'].startswith(d['approval_authority']), f'{tid} auth')
    check('cde_calc.py '+tid in fields['Remarks'], f'{tid} cmd in remarks')
    if d['cde_level']==5:
        check(f'{d["nc_casualty_estimate"]} / {d["ncv"]}' in fields['NC casualty estimate / NCV'], f'{tid} est')
    else:
        check(fields['NC casualty estimate / NCV'].startswith('—'), f'{tid} est dash')
# annex per-target CDE numbers referenced
for tid,lvl,est in [('T-05',5,'4.4'),('T-07',5,'7.9'),('T-08',4,'0.3')]:
    check(est in blocks[tid], f'{tid} annex est {est}')
# approval conclusions in annex
for tid,auth in [('T-01','JFACC'),('T-02','JFACC'),('T-03','JFACC'),('T-04','JFACC'),('T-05','CDR USCENTCOM'),
                 ('T-06','JFACC'),('T-07','STAR'),('T-08','JFACC')]:
    check(auth in blocks[tid].split('**Conclusion:**')[1], f'{tid} annex conclusion authority {auth}')
print('ALL CONSISTENCY CHECKS PASSED' if ok else 'ISSUES FOUND')
EOF"}

